  1441  static int binary_search1(struct insn_reg *insns, unsigned int max, unsigned int id)
  1442  {
  1443          unsigned int first, last, mid;
  1444
  1445          first = 0;
  1446          last = max -1;
  1447
  1448          if (insns[0].insn > id || insns[last].insn < id) {
  1449                  // not found
  1450                  return -1;
  1451          }
  1452
  1453          while (first <= last) {
  1454                  mid = (first + last) / 2;
  1455                  if (insns[mid].insn < id) {
  1456                          first = mid + 1;
  1457                  } else if (insns[mid].insn == id) {
  1458                          return mid;
  1459                  } else {
  1460                          if (mid == 0)
  1461                                  break;
  1462                          last = mid - 1;
  1463                  }
  1464          }
  1465
  1466          // not found
  1467          return -1;
  1468  }
